head.script:
// 테스트 설명, 유효성 값 설정
//  - body 는 화면과 함께 렌더되는 컴포넌트로 $p.dynamicCreate / remove 대상이 아니고
//    공통 생성 함수($c.gcm.createBasicXxx)도 없어 공통 base(common_P_class_1.xml) wrap 패턴을 쓸 수 없다.
//  - class 는 렌더 시점(setRender)에만 반영되는 속성이고 body 는 재생성이 불가하므로
//    con_ 로 값을 바꿔 재생성하는 대신 <body class="oddClass evenClass"> 정적 선언값을 확인한다.
scwin.tData = {
    "description" : "[body > P > class]<br/>Body 컴포넌트에 적용하려는 클래스의 이름을 설정합니다.",
    "validation" : [
        "CSS 파일이나 style 블럭에 정의된 클래스 이름을 공백으로 구분하여 문자열로 설정할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// body 컴포넌트 조회
//  body 는 root 요소라 scope 전역(target1)으로 등록되지 않으므로 정적 선언된 자식(grp_main)의 parentControl 로 조회한다.
scwin.getBody = function () {
    return grp_main.parentControl;
}



// (검증) validation 1 판정 출력 : 렌더된 class 속성과 클래스 스타일(oddClass=border / evenClass=border-radius) 반영 확인
scwin.btn_getStyle_onclick = function (e) {
    let rtn = '';
    let objBody = scwin.getBody();

    wf_body_bottom.getObj("scwin").setReturnValue("class 속성 : " + objBody.render.className);

    rtn = objBody.getStyle("border");
    wf_body_bottom.getObj("scwin").setReturnValue("border : " + rtn);

    rtn = objBody.getStyle("border-radius");
    wf_body_bottom.getObj("scwin").setReturnValue("border-radius : " + rtn);
}
